function business_phone_link(string $label=''): string {
 $phone=(string)settings()['company_phone'];$dial=preg_replace('/[^0-9+]/','',$phone);
 return $dial!==''?'<a class="btn" href="tel:'.h($dial).'">'.h($label!==''?$label.' '.$phone:$phone).'</a>':'';
}
function business_whatsapp_link(string $label='ارتباط در واتساپ'): string {
 $raw=digits(content_text('company.whatsapp',''));if($raw==='')return '';
 $number=str_starts_with($raw,'0')?'98'.substr($raw,1):ltrim($raw,'+');
 return '<a class="btn outline" href="https://wa.me/'.h($number).'?text='.rawurlencode('سلام، برای سفارش عمده نایلکس راهنمایی می‌خواهم.').'" target="_blank" rel="noopener noreferrer">'.h($label).'</a>';
}
