function nylex_products(int $limit=100): array {
 return all("SELECT p.*,c.name category_name FROM ns_products p JOIN ns_categories c ON c.id=p.category_id WHERE p.active=1 AND (c.name LIKE '%نایلکس%' OR c.name LIKE '%نایلون%' OR p.name LIKE '%نایلکس%' OR p.name LIKE '%نایلون%') ORDER BY p.stock>0 DESC,p.featured DESC,p.id DESC LIMIT ".$limit);
}
